import { writeOutput } from "./codegen";

const DOCS_URL = "https://developer.workday.com/documentation";

export async function generate(): Promise<void> {
  writeOutput(
    "workday",
    [
      "// Auto-generated from Workday REST API docs.",
      `// Source: ${DOCS_URL}`,
      "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:workday",
      "//",
      "// DO NOT EDIT THIS FILE MANUALLY.",
      "",
      'import type { FirewallConfig } from "../firewall-types";',
      "",
      "export const workdayFirewall = {",
      '  name: "workday",',
      '  description: "Workday REST APIs",',
      "  placeholders: {",
      '    WORKDAY_TOKEN: "CoffeeSafeLocalCoffeeSafeLocalCoffeeSafeLocal",',
      "  },",
      "  apis: [",
      "    {",
      '      base: "https://${{ vars.WORKDAY_HOST }}",',
      '      hostPolicy: { kind: "providerOwned", suffixes: [".myworkday.com", ".workday.com"] },',
      '      auth: { headers: { Authorization: "Bearer ${{ secrets.WORKDAY_TOKEN }}" } },',
      "      permissions: [],",
      "    },",
      "  ],",
      "} as const satisfies FirewallConfig;",
      "",
    ].join("\n"),
  );
}
